INSERT INTO etos.project (project_code,title,project_status,start_date,target_date,description) VALUES
('ETOS-REF-001','Civilian Research Network Model','KONZEPT','2026-01-15',NULL,'Referenzmodell für ein ziviles internationales Forschungsnetzwerk.'),('ETOS-REF-002','Knowledge Systems and Education','PLANUNG','2026-04-01','2027-03-31','Wissenssysteme für Wissenschaft und Bildung.'),('ETOS-REF-003','Photonics and Metrology Exchange','AKTIV','2026-02-01','2026-12-31','Referenzprojekt für Photonik und Messtechnik.'),('ETOS-REF-004','Sustainable Research Infrastructure','AKTIV','2026-03-15','2027-06-30','Nachhaltige Forschungsinfrastrukturen.') ON CONFLICT (project_code) DO NOTHING;
INSERT INTO etos.publication (title,publication_type,publication_status,publication_date,project_id) SELECT 'ETOS 2.0 Civilian Network Model','WHITEPAPER','PLANUNG',NULL,project_id FROM etos.project WHERE project_code='ETOS-REF-001' UNION ALL SELECT 'Wissenssysteme und Bildungsarchitektur','FORSCHUNGSBERICHT','REVIEW',NULL,project_id FROM etos.project WHERE project_code='ETOS-REF-002' UNION ALL SELECT 'Grundlagen der Photonik-Messtechnik','ARTIKEL','VEROEFFENTLICHT','2026-05-20',project_id FROM etos.project WHERE project_code='ETOS-REF-003';
INSERT INTO etos.funding_program (title,sponsor,amount_eur,funding_status,project_id) SELECT 'Concept Development Grant','Internal planning allocation',25000,'BEWILLIGT',project_id FROM etos.project WHERE project_code='ETOS-REF-001' UNION ALL SELECT 'Education Systems Pilot','Reference funding scenario',85000,'BEANTRAGT',project_id FROM etos.project WHERE project_code='ETOS-REF-002' UNION ALL SELECT 'Photonics Methods Programme','Reference funding scenario',140000,'BEWILLIGT',project_id FROM etos.project WHERE project_code='ETOS-REF-003';
